<?php
namespace App\Http\Controllers;use App\Models\Order;use App\Services\ReturnService;use Illuminate\Http\Request;
class ReturnController extends Controller{public function store(Request $r,Order $order,ReturnService $service){abort_unless($r->user()&&$r->user()->id===$order->user_id,403);$d=$r->validate(['type'=>'required|in:refund,exchange','reason'=>'required|string|max:255','details'=>'nullable|string|max:2000','requested_amount'=>'nullable|numeric|min:0','items'=>'required|array|min:1','items.*.order_item_id'=>'required|exists:order_items,id','items.*.quantity'=>'required|numeric|min:0.01','items.*.condition'=>'nullable|string|max:100']);$return=$service->request($order,$d,$r->user()->id);return redirect()->route('returns.show',$return->uuid);}public function show(string $uuid){$return=\App\Models\ReturnRequest::with(['order','items.orderItem'])->where('uuid',$uuid)->firstOrFail();abort_unless(auth()->id()===$return->user_id,403);return view('storefront.return-status',compact('return'));}}
